type Usage = { model: 'swift' | 'deep'; inputTokens: number; cachedInputTokens: number; outputTokens: number };
type CostReport = { totalCents: number; byModel: { model: string; cents: number }[] };

export function calculateTokenCosts(usage: Usage[]): CostReport {
  const prices: Record<string, { input: number; cached: number; output: number }> = {
    swift: { input: 20, cached: 5, output: 80 },
    deep: { input: 60, cached: 15, output: 240 },
  };
  const totals = new Map<string, number>();
  for (const row of usage) {
    const price = prices[row.model];
    if (!price) throw new Error('Unknown model: ' + row.model);
    const counts = [row.inputTokens, row.cachedInputTokens, row.outputTokens];
    if (counts.some(n => !Number.isSafeInteger(n) || n < 0) || row.cachedInputTokens > row.inputTokens) {
      throw new Error('Invalid token count');
    }
    const cents = ((row.inputTokens - row.cachedInputTokens) * price.input + row.cachedInputTokens * price.cached + row.outputTokens * price.output) / 1000;
    totals.set(row.model, (totals.get(row.model) ?? 0) + cents);
  }
  const byModel = [...totals].sort(([a], [b]) => a.localeCompare(b)).map(([model, cents]) => ({ model, cents: Math.round(cents) }));
  return { totalCents: byModel.reduce((sum, row) => sum + row.cents, 0), byModel };
}
